<template><view class="page"><view class="hero"><text class="brand">之间智造</text><text class="hello">你好，{{ user?.username }}</text><text class="context">{{ contextText }}</text><view class="credit" @tap="go('/pages/recharge/index')"><text>可用积分</text><text class="points">{{ credits }}</text><text>充值 ›</text></view></view><view class="section"><text class="section-title">开始一件新作品</text><view class="grid"><view class="tile" @tap="go('/pages/create/index?mode=image')"><text class="tile-icon">✦</text><text class="tile-title">文字生成图片</text><text>16 积分 / 次</text></view><view class="tile warm" @tap="go('/pages/create/index?mode=text3d')"><text class="tile-icon">◇</text><text class="tile-title">文字生成 3D</text><text>60 积分 / 次</text></view><view class="tile dark" @tap="go('/pages/create/index?mode=image3d')"><text class="tile-icon">◈</text><text class="tile-title">图片生成 3D</text><text>70 积分 / 次</text></view></view></view><view class="quick"><view @tap="go('/pages/works/index')">我的作品 <text>›</text></view><view @tap="go('/pages/purpose/index')">切换创作用途 <text>›</text></view></view><view class="nav"><view @tap="go('/pages/home/index')">⌂<text>首页</text></view><view @tap="go('/pages/create/index')">＋<text>创作</text></view><view @tap="go('/pages/works/index')">▣<text>作品</text></view><view @tap="go('/pages/profile/index')">◉<text>我的</text></view></view></view></template>
<script setup lang="ts">import { computed, onMounted, ref } from 'vue';import { getCredits } from '../../api/creative';import { getSession, requireSession } from '../../utils/session';const user=ref(getSession()?.user);const credits=ref(0);const ctx=ref<any>(uni.getStorageSync('creation_context'));const contextText=computed(()=>ctx.value?.purpose==='museum_sale'?`正在为「${ctx.value.museum?.name||'博物馆'}」创作`:'个人创作工作台');const go=(url:string)=>uni.navigateTo({url});onMounted(async()=>{if(!requireSession())return;try{credits.value=(await getCredits()).balance||0}catch{}});</script>
<style scoped lang="scss">.page{min-height:100vh;padding-bottom:150rpx}.hero{padding:66rpx 38rpx 46rpx;background:linear-gradient(140deg,#402015,#9c4327);color:#fff;border-radius:0 0 42rpx 42rpx}.brand{font-size:28rpx;letter-spacing:5rpx}.hello{display:block;font-size:48rpx;font-weight:700;margin-top:30rpx}.context{display:block;font-size:25rpx;color:#f1cbb1;margin-top:12rpx}.credit{display:flex;align-items:center;gap:16rpx;padding:24rpx;margin-top:36rpx;border-radius:20rpx;background:rgba(255,255,255,.14);font-size:24rpx}.points{font-size:44rpx;font-weight:800;margin-left:auto}.section{padding:38rpx}.section-title{font-size:34rpx;font-weight:750}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20rpx;margin-top:22rpx}.tile{background:#fff;border-radius:26rpx;padding:28rpx;box-shadow:0 12rpx 32rpx rgba(102,50,26,.08);font-size:22rpx;color:#8c7569}.tile:nth-child(3){grid-column:span 2}.warm{background:#fff0df}.dark{background:#442318;color:#f5d8c1}.tile-icon,.tile-title{display:block}.tile-icon{font-size:46rpx;color:#b55230}.tile-title{font-size:28rpx;font-weight:700;color:#332019;margin:18rpx 0 9rpx}.dark .tile-title{color:#fff}.quick{margin:0 38rpx;background:#fff;border-radius:24rpx;padding:0 28rpx}.quick view{padding:30rpx 0;border-bottom:1rpx solid #f0e6e0;font-size:28rpx}.quick view:last-child{border:0}.quick text{float:right;color:#a3482a}.nav{position:fixed;bottom:0;left:0;right:0;background:#fff;display:flex;justify-content:space-around;padding:20rpx 0 env(safe-area-inset-bottom);box-shadow:0 -4rpx 22rpx rgba(74,34,21,.08)}.nav view{text-align:center;color:#8d6c5d;font-size:34rpx}.nav text{display:block;font-size:20rpx;margin-top:4rpx}</style>
